const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-81.1797068176434179, 38.07594286088219]);
  const startDate = '1984-09-17';
  const endDate = '2009-06-02';

  // Split into early and late periods
  const earlyStart = '1984-09-17';
  const earlyEnd = '1985-12-31';
  const lateStart = '2008-01-01';
  const lateEnd = '2009-06-02';

  // 2. Cloud masking function for Landsat 5
  function maskL5sr(image) {
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 3).eq(0)  // Cloud shadow
                   .and(qa.bitwiseAnd(1 << 5).eq(0));  // Cloud
    return image.updateMask(mask);
  }

  // Calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // 3. Data Acquisition - Early Period
  let earlyCol = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(point)
    .filterDate(earlyStart, earlyEnd)
    .map(maskL5sr)
    .map(addNDVI);

  const earlySize = await earlyCol.size().getInfo();
  console.log(`Early period images: ${earlySize}`);

  if (earlySize === 0) {
    console.log('No images found for early period (1984-1985).');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Data Acquisition - Late Period
  let lateCol = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(point)
    .filterDate(lateStart, lateEnd)
    .map(maskL5sr)
    .map(addNDVI);

  const lateSize = await lateCol.size().getInfo();
  console.log(`Late period images: ${lateSize}`);

  if (lateSize === 0) {
    console.log('No images found for late period (2008-2009).');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Calculate median NDVI for each period
  const earlyNDVI = earlyCol.select('NDVI').median();
  const lateNDVI = lateCol.select('NDVI').median();

  // Check valid pixel count
  const earlyStats = await earlyNDVI.reduceRegion({
    reducer: ee.Reducer.count().combine({reducer2: ee.Reducer.mean(), sharedInputs: true}),
    geometry: point,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const lateStats = await lateNDVI.reduceRegion({
    reducer: ee.Reducer.count().combine({reducer2: ee.Reducer.mean(), sharedInputs: true}),
    geometry: point,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const earlyCount = earlyStats['NDVI_count'];
  const earlyMean = earlyStats['NDVI_mean'];
  const lateCount = lateStats['NDVI_count'];
  const lateMean = lateStats['NDVI_mean'];

  console.log(`Early NDVI: ${earlyMean}, Pixels: ${earlyCount}`);
  console.log(`Late NDVI: ${lateMean}, Pixels: ${lateCount}`);

  if (earlyCount === 0 || lateCount === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 6. Validation & Final Answer
  if (earlyMean === null || lateMean === null || 
      earlyMean < -1 || earlyMean > 1 || 
      lateMean < -1 || lateMean > 1) {
    console.log('Invalid NDVI values.');
    console.log('<answer>C3</answer>');
    return;
  }

  const ndviChange = lateMean - earlyMean;
  console.log(`NDVI Change: ${ndviChange.toFixed(4)}`);

  // Deforestation threshold: NDVI decrease > 0.15
  if (ndviChange < -0.15) {
    console.log('Significant NDVI decrease detected - deforestation occurred.');
    console.log('<answer>A</answer>');
  } else {
    console.log('No significant NDVI decrease - no deforestation detected.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
